action.mutation:
mutation CreateProductionSetup($payload: [ProductionSetupCreatePayloadInput!]!) {
  mutation: createProductionSetup(payload: $payload) { 
    id
    workcenterId
  }
}

mutation UpdateProductionSetup($payload: [ProductionSetupUpdatePayloadInput!]!) {
  mutation: updateProductionSetup(payload: $payload) { 
    id
    workcenterId
  }
}

mutation DeleteProductionSetup($payload: [ProductionSetupDeletePayloadInput!]!) {
  mutation: deleteProductionSetup(payload: $payload) { 
    id
    workcenterId
  }
}

action.transformation:
(
  $startNewRun := $showConfirmDialog("If a new production run is NOT started any current runs will be closed when we import the new setups.", 
    { 
    'title': "Start a new produciton run?",
    'delayTimeinSeconds' : 5,
    'icon' : 'check',
    'buttonColor': 'confirm'
    }
  );

  data.productionRun? $executeFlow("startStopRun",{ "workcenterId": rowData.workcenter.id});

  /* Sync */  
  $executeFlow("plexApiProductionSetups", { "workcenterId": rowData.workcenter.id });

  $startNewRun? $executeFlow("startStopRun",{ "workcenterId": rowData.workcenter.id});


)
